/*
 * Each outfit renders in up to three passes around the arms and head:
 *   back  — behind the body (veils, pallu falls, stole backs)
 *   body  — legs, garment, necklines, embroidery
 *   front — in front of the arms (rare: drapes that fall over the forearm)
 */
export type OutfitLayers = { back?: React.ReactNode; body: React.ReactNode; front?: React.ReactNode };

const LONG = "M120 226 C138 213 170 206 186 204 L214 204 C230 206 262 213 280 226 L286 300 L278 470 C284 540 294 600 304 662 L96 662 C106 600 116 540 122 470 L114 300 Z";
