  `M120 226 C138 213 170 206 186 204 L214 204 C230 206 262 213 280 226 L286 300 L278 470 L282 ${bottom} L118 ${bottom} L122 470 L114 300 Z`;
const SHADE_SIDE = (bottom: number) => `M120 226 L114 300 L122 470 L116 ${bottom} L138 ${bottom} C140 420 140 300 142 230 Z`;

const Neck: React.FC<{ skin: string; female?: boolean }> = ({ skin, female }) => (
  <g>
    <path d={female ? "M186 166 L186 214 L214 214 L214 166 Z" : "M182 168 L182 212 L218 212 L218 168 Z"} fill={tone(skin, -0.08)} />
    <path d={female ? "M186 172 C194 184 206 184 214 172 L214 180 C206 190 194 190 186 180 Z" : "M182 172 C192 186 208 186 218 172 L218 182 C208 194 192 194 182 182 Z"} fill={tone(skin, -0.2)} opacity={0.6} />
  </g>
);

const Buttons: React.FC<{ ys: number[]; x?: number; r?: number; color?: string }> = ({ ys, x = 200, r = 4.6, color }) => (
  <g>
    {ys.map((y) => (
      <g key={y}>
        <circle cx={x} cy={y} r={r} fill={color ?? "url(#foil)"} />
        <circle cx={x - r * 0.3} cy={y - r * 0.3} r={r * 0.3} fill="#FFF6DC" opacity={0.7} />
      </g>
    ))}
  </g>
);

