const PEARLS = (strand: number) => {
  const pts: React.ReactNode[] = [];
  const depth = 22 + strand * 11;
  for (let i = 0; i <= 18; i++) {
    const t = i / 18;
    const x = 176 + t * 48;
    const y = 208 + Math.sin(t * Math.PI) * depth;
    pts.push(<circle key={i} cx={x} cy={y} r={2.4} fill="#F7F1E4" stroke="#D8CDB6" strokeWidth={0.5} />);
  }
  return pts;
};

