export const outfitLayers = (o: Outfit, p: Person): OutfitLayers => {
  switch (o.kind) {
    case "sherwani":
      return sherwani(o, p);
    case "bandhgala":
      return bandhgala(o, p);
    case "suit":
      return suit(o, p);
    case "blazerTee":
      return blazerTee(o, p);
    case "casualShirt":
      return casualShirt(o, p);
    case "saree":
      return saree(o, p);
    case "lehenga":
      return lehenga(o, p);
  }
};
